content:
:root {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  line-height: 1.5;
  color-scheme: light dark;
  color: #213547;
  background-color: #f8fafc;
}

body {
  margin: 0;
  display: flex;
  place-content: center;
  min-width: 320px;
  min-height: 100vh;
}

#root {
  width: 100%;
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem;
  box-sizing: border-box;
}

.app-container {
  background-color: #ffffff;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  padding: 2rem;
  width: 100%;
  box-sizing: border-box;
}

.header {
  margin-bottom: 1.5rem;
}

.title {
  font-size: 1.85rem;
  font-weight: 700;
  color: #1e293b;
  margin: 0 0 1rem 0;
}

.search-container {
  margin-bottom: 1.5rem;
}

.search-input {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  box-sizing: border-box;
}

.search-input:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.table-container {
  overflow-x: auto;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
}

.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

.employee-table th,
.employee-table td {
  padding: 0.875rem 1rem;
  border-bottom: 1px solid #e2e8f0;
}

.employee-table th {
  background-color: #f1f5f9;
  font-weight: 600;
  color: #475569;
}

.th-sortable {
  cursor: pointer;
  user-select: none;
  transition: background-color 0.2s;
}

.th-sortable:hover {
  background-color: #e2e8f0;
  color: #1e293b;
}

.employee-table tbody tr:last-child td {
  border-bottom: none;
}

.employee-table tbody tr:hover {
  background-color: #f8fafc;
}

.no-result {
  text-align: center;
  padding: 2rem;
  color: #64748b;
  font-style: italic;
}

@media (max-width: 640px) {
  #root {
    padding: 1rem;
  }

  .app-container {
    padding: 1rem;
  }

  .title {
    font-size: 1.5rem;
  }
}

export interface Employee {
  id: string;
  name: string;
  department: string;
  age: number;
}

export type SortField = 'name' | 'department' | 'age';

export type SortOrder = 'asc' | 'desc';

import { Employee, SortField, SortOrder } from './types';
import './index.css';

interface EmployeeTableProps {
  employees?: Employee[];
  sortField: SortField;
  sortOrder: SortOrder;
  onSort: (field: SortField) => void;
}

export default function EmployeeTable({
  employees = [],
  sortField,
  sortOrder,
  onSort,
}: EmployeeTableProps) {
  const renderSortIcon = (field: SortField) => {
    if (sortField !== field) return ' ↕';
    return sortOrder === 'asc' ? ' ▲' : ' ▼';
  };

  return (
    <div className="table-container">
      <table className="employee-table">
        <thead>
          <tr>
            <th className="th-sortable" onClick={() => onSort('name')}>
              名前{renderSortIcon('name')}
            </th>
            <th className="th-sortable" onClick={() => onSort('department')}>
              部署{renderSortIcon('department')}
            </th>
            <th className="th-sortable" onClick={() => onSort('age')}>
              年齢{renderSortIcon('age')}
            </th>
          </tr>
        </thead>
        <tbody>
          {employees.length === 0 ? (
            <tr>
              <td colSpan={3} className="no-result">
                該当する社員が見つかりません。
              </td>
            </tr>
          ) : (
            employees.map((emp) => (
              <tr key={emp.id}>
                <td>{emp.name}</td>
                <td>{emp.department}</td>
                <td>{emp.age}</td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { Employee, SortField, SortOrder } from './types';
import EmployeeTable from './EmployeeTable';
import './index.css';

const initialEmployees: Employee[] = [
  { id: '1', name: '佐藤 健', department: '開発部', age: 28 },
  { id: '2', name: '鈴木 美咲', department: '人事部', age: 34 },
  { id: '3', name: '高橋 翔', department: '営業部', age: 41 },
  { id: '4', name: '田中 葵', department: '開発部', age: 25 },
  { id: '5', name: '伊藤 蓮', department: 'マーケティング部', age: 30 },
  { id: '6', name: '渡辺 さくら', department: '営業部', age: 27 },
  { id: '7', name: '山本 大輝', department: '総務部', age: 39 },
  { id: '8', name: '中村 美羽', department: '人事部', age: 32 },
  { id: '9', name: '小林 陸', department: '開発部', age: 29 },
  { id: '10', name: '加藤 陽菜', department: 'マーケティング部', age: 26 },
];

export default function App() {
  const [employees] = useState<Employee[]>(initialEmployees);
  const [searchTerm, setSearchTerm] = useState('');
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('asc');
    }
  };

  const filteredAndSortedEmployees = useMemo(() => {
    const filtered = employees.filter((emp) =>
      emp.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return filtered.sort((a, b) => {
      const aVal = a[sortField];
      const bVal = b[sortField];

      if (typeof aVal === 'string' && typeof bVal === 'string') {
        const comp = aVal.localeCompare(bVal, 'ja');
        return sortOrder === 'asc' ? comp : -comp;
      } else {
        if (aVal < bVal) return sortOrder === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortOrder === 'asc' ? 1 : -1;
        return 0;
      }
    });
  }, [employees, searchTerm, sortField, sortOrder]);

  return (
    <div className="app-container">
      <div className="header">
        <h1 className="title">社員名簿</h1>
        <div className="search-container">
          <input
            type="text"
            className="search-input"
            placeholder="名前で絞り込み検索..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>
      <EmployeeTable
        employees={filteredAndSortedEmployees}
        sortField={sortField}
        sortOrder={sortOrder}
        onSort={handleSort}
      />
    </div>
  );
}
